update service_package
category_id = #{categoryId}, name = #{name}, price = #{price}, original_price = #{originalPrice}, image = #{image}, description = #{description}, duration = #{duration}, service_mode = #{serviceMode}, sales = #{sales}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select sp.*, c.name as categoryName from service_package sp left outer join category c on sp.category_id = c.id
and sp.name like concat('%', #{name}, '%')
and sp.category_id = #{categoryId}
and sp.status = #{status}
order by sp.create_time desc

